def _static_fallback(ctx, comp, I, fs):
    """Server-rendered summary inside <main>: visible when scripts are blocked or fail (IDE previews, strict viewers).
    The interactive dashboard replaces it as soon as the script runs."""
    from html import escape as e
    SEVS = ("critical", "high", "medium", "low", "info")
    cnt = {k: sum(1 for f in fs if f.get("severity") == k) for k in SEVS}
    rows = sorted(fs, key=lambda f: (SEVS.index(f["severity"]) if f.get("severity") in SEVS else 9, 0 if f.get("status") == "confirmed" else 1))[:60]
    rate = "".join(f"<div class='card'><b>{e(k.upper())}</b> <span style='font-size:28px;font-weight:800'>{e(str(comp[k]))}</span></div>" for k in ("reliability", "security", "maintainability"))
    conds = "".join(f"<li>{'✔' if ok else '✘'} {e(str(n))}: <b>{e(str(v))}</b></li>" for n, ok, v in comp["conditions"])
    sev = " · ".join(f"{k} <b>{cnt[k]}</b>" for k in SEVS)
    body = "".join(f"<tr><td>{e(str(f.get('severity', '')))}</td><td><b>{e(str(f.get('title', '')))}</b><br><span class='small mut'>{e(str(f.get('fix') or '')[:240])}</span></td>"
                   f"<td>{e(str((f.get('location') or {}).get('file', '')))}:{e(str((f.get('location') or {}).get('line', '')))}</td></tr>" for f in rows)
    return (f"<div id='static-fallback'><h1>{e(str(ctx['meta'].get('repo', '')))}</h1><div class='grid g4' style='margin:12px 0'>{rate}</div>"
            f"<div class='card'><h3>{I['conditions']}</h3><ul>{conds}</ul><p>{sev}</p></div>"
            f"<div class='card' style='margin-top:14px;overflow:auto'><h3>Top {len(rows)} / {len(fs)}</h3><table><thead><tr><th>Sev</th><th>{I['title']}</th><th>{I['file']}</th></tr></thead><tbody>{body}</tbody></table></div>"
            f"<noscript><p class='small mut'>JavaScript is disabled: this is the static summary. Open report.html in a browser with scripts enabled (Chrome, Firefox, Safari, Edge) for the interactive dashboard, or read REPORT.md.</p></noscript></div>")


ERR_JS = """window.addEventListener('error',function(e){try{var m=document.getElementById('main');if(!m)return;var b=document.createElement('div');b.className='card';b.style.cssText='border-color:#dc2626;margin-bottom:12px';b.textContent='Interactive view failed ('+(e.message||'error')+'). Showing the static summary; the full findings are in findings.json / REPORT.md.';m.insertBefore(b,m.firstChild)}catch(x){}});"""


