GATE_PASS = f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{_SH}<path d="M8.6 12.2l2.5 2.5 4.3-4.8"/></svg>'
GATE_FAIL = f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{_SH}<path d="M9.4 9.6l5.2 5.2M14.6 9.6l-5.2 5.2"/></svg>'


def _load_pack(lang):
    """Language pack from engine/locales/<lang>.json (read directly: this module may be loaded without its package)."""
    import os as _os
    try: return json.load(open(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "locales", lang + ".json"), encoding="utf-8"))
    except (OSError, ValueError): return {}


def _hex_ok(h):
    return isinstance(h, str) and len(h) == 7 and h[0] == "#" and all(c in "0123456789abcdefABCDEF" for c in h[1:])


def _lum(h):
    f = lambda c: c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = (f(int(h[i:i + 2], 16) / 255) for i in (1, 3, 5))
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def _ink(h):
    """Text color with the best contrast on background h (white or near-black)."""
    l = _lum(h)
    return "#ffffff" if (1.05 / (l + 0.05)) >= ((l + 0.05) / 0.06) else "#0b1020"


def _lighten(h, k=0.18):
    """Dark-theme variant of the brand color: lighter, but never washed out."""
    r, g, b = (int(h[i:i + 2], 16) for i in (1, 3, 5))
    out = "#%02x%02x%02x" % tuple(int(c + (255 - c) * k) for c in (r, g, b))
    return out if _lum(out) < 0.55 else h


def _medallions(m):
    """Framework medallions (pictogram + readiness ring) for the compliance cards; same art as the README badges."""
    import importlib.util, os
    sp = importlib.util.spec_from_file_location("pn_fwart", os.path.join(os.path.dirname(os.path.abspath(__file__)), "fwart.py")); mod = importlib.util.module_from_spec(sp); sp.loader.exec_module(mod); medallion = mod.medallion
    out = {}
    for x in ((m.get("compliance") or {}).get("frameworks") or []):
        v = x.get("readiness"); col = "#6b7280" if v is None else "#22c55e" if v >= 85 else "#84cc16" if v >= 65 else "#f59e0b" if v >= 45 else "#f97316" if v >= 25 else "#ef4444"
        out[x["id"]] = medallion(x["id"], v, 104, col, x.get("name"))
    return out



def _logos(m):
    """Original logos for the detected stack (languages, frameworks, evidence, databases)."""
    import importlib.util, os
    sp = importlib.util.spec_from_file_location("pn_techlogos", os.path.join(os.path.dirname(os.path.abspath(__file__)), "techlogos.py")); mod = importlib.util.module_from_spec(sp); sp.loader.exec_module(mod)
    names = list((m.get("languages") or {}).keys()) + list(m.get("frameworks") or [])
    for v in ((m.get("plan") or {}).get("evidence") or {}).values(): names += [x for x in v if isinstance(x, str)]
    for d in (m.get("databases") or []):
        names += [d] if isinstance(d, str) else [d.get("engine") or d.get("name") or ""] if isinstance(d, dict) else []
    return mod.for_names([n for n in dict.fromkeys(names) if n])



def _plan(findings, lang, label):
    """Fix plan (engine/fixplan.py): one ordered, complete plan shared by the dashboard, fix-plan.md and AI assistants."""
    import importlib.util, os
    sp = importlib.util.spec_from_file_location("pn_fixplan", os.path.join(os.path.dirname(os.path.abspath(__file__)), "fixplan.py")); mod = importlib.util.module_from_spec(sp); sp.loader.exec_module(mod)
    plan = mod.build(findings, lang, label)
    return plan, mod.to_md(plan, lang)



def _brand_css(br):
    """Project's own primary/secondary colors override the accent variables (validated hex only)."""
    p = (br or {}).get("primary"); sd = (br or {}).get("secondary") or p
    if not _hex_ok(p): return ""
    sd = sd if _hex_ok(sd) else p
    lp, ls = _lighten(p), _lighten(sd)
    return (f":root{{--brand:{p};--brand2:{sd};--on-brand:{_ink(p)}}}:root[data-theme=dark]{{--brand:{lp};--brand2:{ls};--on-brand:{_ink(lp)}}}"
            f"@media(prefers-color-scheme:dark){{:root:not([data-theme=light]){{--brand:{lp};--brand2:{ls};--on-brand:{_ink(lp)}}}}}")


def build(ctx, t, lang, limits_txt):
    pk = _load_pack(lang)
    I = dict(I18N["en"]); I.update(I18N.get(lang, {})); I.update(pk.get("ui", {}))
    keep = ("id", "fingerprint", "type", "category", "severity", "status", "rule", "title", "location", "evidence", "impact", "fix", "effort_min", "cwe", "owasp", "needs_validation_reason", "priority",
            "explanation", "newbie", "fix_steps", "bad_example", "safe_example", "verify", "triage", "family", "title_family", "snippet", "legacy", "seo_cat")
    fs = [{k: f.get(k) for k in keep if f.get(k) is not None} for f in ctx["all"]]
    comp = {k: ctx["comp"][k] for k in ("reliability", "security", "maintainability", "debt_ratio", "debt_min", "conditions", "gate_pass")}
    m = dict(ctx["metrics"]); m.pop("skipped_files", None)
    plan_, plan_md_ = _plan(ctx["all"], lang, ctx["meta"].get("repo", ""))
    data = dict(plan=plan_, plan_md=plan_md_, logos=_logos(m), fwm=_medallions(m), src=ctx.get("sources") or {}, x=pk.get("x", {}), i18n=I, findings=fs, metrics=m, comp=comp, meta=ctx["meta"], owasp=ctx["owasp"], ledger=ctx["ledger"], limits=limits_txt)
    blob = json.dumps(data, ensure_ascii=False).replace("</", "<\\/").replace("<!--", "<\\u0021--").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    bl = ((ctx["metrics"].get("brand") or {}).get("logo") or {}).get("data_uri")
    client_logo = f'<img class="clogo" src="{bl}" alt="">' if isinstance(bl, str) and bl.startswith("data:image/") else ""
    gate_cls = "gate-ok" if comp["gate_pass"] else "gate-no"
    name = (ctx["meta"].get("repo") or "")
    return f"""<!doctype html><html lang="{pk.get('html_lang') or lang}" dir="{pk.get('dir') or 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PN-Ultra-Audit · {name}</title>
<link rel="icon" href="data:image/svg+xml;utf8,{LOGO_SVG.replace('#', '%23').replace('"', "'").replace(chr(10), '')}"><style>{CSS}{_brand_css(ctx['metrics'].get('brand'))}</style></head><body>
<header class="top"><div class="logo">{LOGO_SVG}</div><div class="brand">PN-Ultra-Audit<small>{name} · run #{ctx['meta'].get('run', '')} · {ctx['meta'].get('date', '')}</small></div><span class="pill {gate_cls}">{GATE_PASS if comp['gate_pass'] else GATE_FAIL}{I['gate']}: {I['passed'] if comp['gate_pass'] else I['failed']}</span><span class="grow"></span>{client_logo}<button class="btn" id="print">PDF</button><button class="btn" id="edcfg" title="Editor: set project folder" aria-label="editor">&#128193;</button><button class="btn" id="theme">◐</button></header>
<div class="wrap"><nav id="nav"></nav><main id="main">{_static_fallback(ctx, comp, I, fs)}</main></div><div class="mask" id="mask"></div><aside class="drawer" id="drawer"></aside><div class="toast" id="toast"></div>
<script>{ERR_JS}</script><script id="data" type="application/json">{blob}</script><script>{JS}</script></body></html>"""
